import{_ as l,l as n,o as a,c as o,v as t,p as s,x as r,d,i as p,S as b}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"WebGPU 推理","description":"","frontmatter":{"title":"WebGPU 推理","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/webgpu-inference.md","filePath":"llm/webgpu-inference.md","lastUpdated":1789023840000}'),h={name:"llm/webgpu-inference.md"};function m(P,e,c,W,_,f){const i=n("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="webgpu-推理" tabindex="-1">WebGPU 推理 <a class="header-anchor" href="#webgpu-推理" aria-label="Permalink to &quot;WebGPU 推理&quot;">​</a></h1><div class="epigraph"><p>浏览器里的 GPU 没有 CUDA 运行时：计算着色器加上严格的内存配额，能跑的是量化后的小模型，不是把 vLLM 搬进标签页。</p><footer>—— W3C WebGPU；浏览器 LLM 见 MLC WebLLM 与 transformers.js 一类 TVM / ONNX Runtime Web 路径</footer></div><p><a href="/llm/mlx-apple">上一课</a>还有原生进程与统一内存。WebGPU 把计算放进沙箱：着色器、缓冲配额、无自定义特权内核。MLC 的 WebLLM 用 TVM 把模型编译到 WebGPU；transformers.js 常用 ONNX Runtime Web 或 WASM。本课写约束：权重要下载到浏览器、KV 占 JS/GPU 缓冲、decode 在带宽与启动开销双重劣势下跑。隐私（权重与数据不出页）是产品动机，不是性能动机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>下载 4-bit 7B 仍是数 GB，首次 TTFT 含网络。配额与移动浏览器会直接拒绝。逐步：没有 <a href="/llm/flashattention">FlashAttention</a> 那种 CUDA 核，注意力是着色器或退化实现，\\(n\\) 稍长即炸。缺口是承认 Web 路径的模型级（1B–8B 量化、短上下文），以及预填充与 decode 的着色器启动开销。采样在 JS 或 WASM，词表扫描相对 GPU 着色器可能更刺眼——先修采样器内核的反面。</p><p>没有连续批：一页一个用户，\\(B=1\\)，工作点永远在带宽区。优化是量化、减层、短上下文，不是堆并发。</p><p><span class="marginnote">WebGPU 与 WebGL 不同。旧的 WebGL 路径不适合通用计算。检测能力失败时应回退 WASM CPU，并明确更慢。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译：TVM / ORT 把图降到 WGSL。分发：分片下载、缓存到 Origin Private File System。KV：固定最大 \\(n\\) 预留，碎片回到 OpenVINO NPU 那类问题。流式：id 在 Worker 里 generate，主线程 detokenize，注意 UTF-8 稳定前缀。投机在浏览器上草稿也得是小模型或早退，下一课端侧投机再写；Web 上内存更紧。</p>',9)),(a(),s(b,null,{default:r(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E5%88%86%E7%89%87%E4%B8%8B%E8%BD%BD%E6%9D%83%E9%87%8D%22%5D%20--%3E%20COMP%5B%22TVM%2FORT%20%E2%86%92%20WebGPU%22%5D%0A%20%20COMP%20--%3E%20STEP%5B%22%E7%9D%80%E8%89%B2%E5%99%A8%E4%B8%80%E6%AD%A5%20decode%22%5D%0A%20%20STEP%20--%3E%20JS%5B%22JS%2FWASM%20%E9%87%87%E6%A0%B7%22%5D%0A%20%20JS%20--%3E%20UI%5B%22%E7%A8%B3%E5%AE%9A%E5%89%8D%E7%BC%80%E4%B8%8A%E5%B1%8F%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>沙箱禁止持久内核与无限显存。每步着色器启动相对 CUDA Graph 更贵，小核更多伤。会计公式仍用，\\(B_{\\mathrm{HBM}}\\) 换成共享显存或系统内存。安全：模型文件来自源站，仍要完整性校验，避免恶意着色器或权重。这与 safetensors 的供应链同一类，只是运行在浏览器官辖。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要承诺「在标签页跑 70B」。不要在 iOS Safari 的不稳定 WebGPU 上无检测直跑。下一课：真正的手机 NPU 部署，权限与工具链又不同。</p><p>出处：W3C WebGPU；MLC WebLLM；ORT Web。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WebGPU 推理是沙箱着色器 + 下载配额；\\(B=1\\)、短上下文、强量化。</li><li>无 CUDA FA；长 \\(n\\) 先炸内存再谈算法。</li><li>首次延迟含下载；要用分片缓存。</li><li>采样与 detokenize 在 Worker；注意稳定前缀。</li><li>产品动机常是隐私与零安装，不是吞吐。</li><li>下一课：移动端 NPU。</li><li>出处：W3C WebGPU；MLC WebLLM。</li></ul>',7))])}const A=l(h,[["render",m]]);export{E as __pageData,A as default};
